{"version":"1.0","createSurface":{"surfaceId":"webhooks_test","catalogId":"https://a2ui.org/specification/v1_0/catalogs/basic/catalog.json","sendDataModel":true,"components":[{"id":"root","component":"Column","children":["ok","secret_title","secret","samples_title","samples","feedback_card"]},{"id":"ok","component":"Alert","tone":"success","title":"Endpoint created in test mode","text":"Lumen will POST payment.succeeded and refund.created to https://shop.example.com/hooks/lumen","@catalogId":"https://github.com/AIDotNet/TKCode.Arc/a2ui/catalogs/arc/v1"},{"id":"secret_title","component":"Text","text":"### Signing secret"},{"id":"secret","component":"CodeBlock","code":"whsec_test_8f2c41d07a","language":"text","fileName":".env","@catalogId":"https://github.com/AIDotNet/TKCode.Arc/a2ui/catalogs/arc/v1"},{"id":"samples_title","component":"Text","text":"### Verify and handle the request"},{"id":"samples","component":"Accordion","expanded":0,"items":[{"title":"C# (ASP.NET Core)","child":"code_cs"},{"title":"Python (FastAPI)","child":"code_py"},{"title":"Register with cURL","child":"code_curl"}],"@catalogId":"https://github.com/AIDotNet/TKCode.Arc/a2ui/catalogs/arc/v1"},{"id":"code_cs","component":"CodeBlock","code":"app.MapPost(\"/hooks/lumen\", async (HttpRequest request) =>\n{\n    var body = await new StreamReader(request.Body).ReadToEndAsync();\n    var signature = request.Headers[\"Lumen-Signature\"].ToString();\n    if (!LumenSignature.Verify(body, signature, secret))\n    {\n        return Results.Unauthorized();\n    }\n\n    var evt = JsonSerializer.Deserialize(body, LumenJson.Default.LumenEvent);\n    // ... handle evt.Type\n    return Results.Ok();\n});","language":"csharp","fileName":"Program.cs","@catalogId":"https://github.com/AIDotNet/TKCode.Arc/a2ui/catalogs/arc/v1"},{"id":"code_py","component":"CodeBlock","code":"@app.post(\"/hooks/lumen\")\nasync def lumen_hook(request: Request):\n    body = await request.body()\n    if not lumen.verify(body, request.headers[\"Lumen-Signature\"], SECRET):\n        raise HTTPException(status_code=401)\n    event = json.loads(body)\n    # ... handle event[\"type\"]\n    return {\"ok\": True}","language":"python","fileName":"hooks.py","@catalogId":"https://github.com/AIDotNet/TKCode.Arc/a2ui/catalogs/arc/v1"},{"id":"code_curl","component":"CodeBlock","code":"curl https://api.lumenpay.example/v1/webhooks \\\n  -H \"Authorization: Bearer $LUMEN_KEY\" \\\n  -d url=https://shop.example.com/hooks/lumen \\\n  -d \"events[]=payment.succeeded\" \\\n  -d \"events[]=refund.created\"","language":"bash","@catalogId":"https://github.com/AIDotNet/TKCode.Arc/a2ui/catalogs/arc/v1"},{"id":"feedback_card","component":"Card","child":"feedback"},{"id":"feedback","component":"Row","align":"center","children":["feedback_text","stars","send"]},{"id":"feedback_text","component":"Text","text":"Was this guide clear?"},{"id":"stars","component":"Rating","weight":1,"value":{"@path":"/stars"},"@catalogId":"https://github.com/AIDotNet/TKCode.Arc/a2ui/catalogs/arc/v1"},{"id":"send","component":"Button","child":"send_label","action":{"event":{"name":"rate_guide","context":{"stars":{"@path":"/stars"}}}},"variant":"default","@checks":[{"condition":{"@call":"numeric","args":{"value":{"@path":"/stars"},"min":1}},"message":"Pick 1 to 5 stars."}]},{"id":"send_label","component":"Text","text":"Send"}],"dataModel":{"stars":0}}}
